#!/usr/bin/env bash
# regen.sh — rebuild every file kit generates from design/, from nothing, and
# prove the result is what is committed (`make regen`; ADR 0163).
#
# kit gen -check already says the generated files are the design's. This says
# more: with every one of them DELETED, the design alone writes them back,
# byte for byte, and `make api` then writes docs/api, docs/error-codes.yaml and
# the BUILD files back too. It is stage 1 of "kit regenerates the SDK from
# zero".
#
# A generated file is known by its HEADER, never by its name: its first line is
#   // Code generated by kit from <design file> (sha256 <hex>, body <hex>). DO NOT EDIT.
# — the line tools/genindex/digests.go's kitHeader matches: the pins, the
# ports, codes_gen*.go, perf_gen_test.go, facade_gen.go and decl_gen.go alike. A glob
# such as `*_gen*.go`
# also matches hand-written files (registry_generic.go,
# facade_generics_external_test.go), which kit would never write back, and a
# perf_fixtures_test.go beside a perf_gen_test.go is the owner's, not kit's.
#
# It needs kit, the owner's tool, which is not public: it is a local target
# and no CI lane runs it. The kit it runs must be the one design/sdk.yaml pins
# (project.kit.version), or it refuses before touching anything.
#
# It starts from a working tree with no tracked change, since the closing
# `git diff --exit-code` would otherwise report the caller's edits as its own,
# and with no untracked generated file, which it refuses rather than deletes.
# Only tracked files are deleted; any file the regeneration adds that git does
# not track — a Go file, a docs/api document, a BUILD.bazel — fails it.
#
# Runs under macOS's /bin/bash 3.2 and the BSD tools (scripts/CLAUDE.md).
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root"

die() {
  printf 'regen: %s\n' "$1" >&2
  exit 1
}

# The pinned kit: design/sdk.yaml's project.kit.version (scripts/kit-pinned.sh,
# shared with from-zero.sh and kit-coverage.sh).
# shellcheck source=scripts/kit-pinned.sh
. scripts/kit-pinned.sh
kit_pinned regen || exit 1

[ -z "$(git status --porcelain --untracked-files=no)" ] ||
  die "the working tree has uncommitted changes; commit or stash them first"

header=$KIT_HEADER

list="$(mktemp "${TMPDIR:-/tmp}/regen.XXXXXX")"
before="$(mktemp "${TMPDIR:-/tmp}/regen.XXXXXX")"
after="$(mktemp "${TMPDIR:-/tmp}/regen.XXXXXX")"
trap 'rm -f "$list" "$before" "$after"' EXIT

# The files git does not track, now: whatever kit gen or make api adds beside
# them — a generated Go file, a docs/api document, a BUILD.bazel — is a
# difference the closing `git diff` cannot see, so it is compared after.
git ls-files --others --exclude-standard | LC_ALL=C sort >"$before"

# Every file whose FIRST line is the header, among the files listed (-z) on
# standard input; git grep narrows the tree to candidates, the line decides.
with_header() {
  while IFS= read -r -d '' f; do
    first="$(head -n 1 "$f")"
    if [[ $first =~ $header ]]; then
      printf '%s\n' "$f"
    fi
  done
}

# An untracked generated file is refused, never deleted: the proof is about
# what is committed, and deleting a file nobody committed loses work.
stray="$(git ls-files -z --others --exclude-standard -- '*.go' | with_header | tr '\n' ' ')"
[ -z "$stray" ] || die "untracked files carry the kit header; commit or remove them first: $stray"

# Only TRACKED files are deleted.
git grep -l -z -e '^// Code generated by kit from ' -- '*.go' | with_header >"$list" || true
n="$(wc -l <"$list" | tr -d ' ')"
[ "$n" -gt 0 ] || die "no file carries the kit header; nothing to regenerate"
printf 'regen: deleting %s generated files\n' "$n"
while IFS= read -r f; do
  rm -f -- "$f"
done <"$list"

# kit gen also owns a SECTION of a hand-written file: the lines from
# `# BEGIN kit gen` to `# END kit gen` at the end of tools/alloc-lane-targets.txt
# (ADR 0165), which it appends after one blank line when absent. The section
# and that blank line are removed, so it too is written back from the design;
# the hand-written lines above it stay byte for byte.
section=tools/alloc-lane-targets.txt
if grep -q '^# BEGIN kit gen' "$section"; then
  printf 'regen: clearing the kit gen section of %s\n' "$section"
  kit_clear_section "$section"
fi

printf 'regen: kit gen\n'
kit gen
printf 'regen: make api\n'
make --no-print-directory api

# No file may appear that git did not already know as untracked.
git ls-files --others --exclude-standard | LC_ALL=C sort >"$after"
added="$(LC_ALL=C comm -13 "$before" "$after")"
[ -z "$added" ] || die "regeneration wrote files git does not track:
$added"

if ! git diff --exit-code --stat; then
  die "regeneration differs from what is committed (git diff above)"
fi
printf 'regen: %s files regenerated, zero diff\n' "$n"
